(() => {
'use strict';
const M=BatteryModel,$=id=>document.getElementById(id),svg=$('network'),world=$('world'),ns='http://www.w3.org/2000/svg',roughSvg=rough.svg(svg);
const C={ink:'#26343e',memory:'#2f8452',hidden:'#7653a2',warning:'#b94a43',input:'#a67822',active:'#4f6c7c'};
let cfg=M.config(),warning=true,models={},traces={},backs={},batches={},lastUpdates={},mode='forward',index=0,steps=[],expanded=[],offsets=[],playing=false,training=false,timer=null,trainTimer=null,frame=null,serial=0,view='focus',camera={x:0,y:0,k:1},drag=null;
const fwd=['Inputs','Forget gate','Input gate','Candidate','Retain & write','Cell state','Output gate','Hidden state','Pass forward'];
const bwd=['Incoming gradient','Memory gradient','Output-gate derivative','Forget-gate derivative','Input-gate derivative','Candidate derivative','Pass gradients backward','Accumulate weight gradients'];
const kind=()=>$('inspect-model').value,unit=()=>Number($('unit').value)||0,T=()=>cfg.gap+2,token=t=>t===0?(warning?'Warning':'Normal'):t===T()-1?'Inspect':'Normal';
const num=v=>!Number.isFinite(v)?String(v):Math.abs(v)>0&&(Math.abs(v)<.0001||Math.abs(v)>=10000)?v.toExponential(3):v.toFixed(4);
const vec=a=>'['+a.map(num).join(', ')+']';
const seed=s=>{let n=19;for(const ch of s)n=(n*31+ch.charCodeAt(0))%2147483647;return n||19;};
function el(tag,a={},text=''){const e=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(a))e.setAttribute(k,v);if(text)e.textContent=text;return e;}
function text(g,x,y,s,cls='',anchor='middle'){g.append(el('text',{x,y,class:cls,'text-anchor':anchor},s));}
function box(g,x,y,w,h,title,value,active=false){g.append(roughSvg.rectangle(x,y,w,h,{seed:seed(title+':'+x+':'+y),roughness:1.15,stroke:active?C.active:C.ink,strokeWidth:1.35,fill:active&&title?'#dbe8eb':'#fffefa',fillStyle:active&&title?'hachure':'solid',hachureGap:5,fillWeight:.4}));if(title)text(g,x+w/2,y+h/2-5,title);if(value)text(g,x+w/2,y+h/2+19,value,'value');}
function op(g,x,y,s,active=false){g.append(roughSvg.circle(x,y,32,{seed:seed(s+x+y),roughness:1.1,stroke:active?C.active:C.ink,strokeWidth:1.4,fill:'#fffefa',fillStyle:'solid'}));text(g,x,y+6,s);}
function path(g,d,id,color=C.ink,active=false){const original=el('path',{d,'data-route':id,class:'motion-path'});g.append(original);const sketch=roughSvg.path(d,{seed:seed(id),stroke:color,strokeWidth:active?2.7:1.5,roughness:.7});const ps=sketch.querySelectorAll('path');if(ps.length)ps[ps.length-1].setAttribute(mode==='backward'?'marker-start':'marker-end','url(#arrow)');g.append(sketch);}
function refresh(){for(const k of ['RNN','LSTM']){traces[k]=M.forward(models[k],M.sequence(cfg,warning),warning?1:0);backs[k]=M.backward(models[k],traces[k]);batches[k]=M.batch(models[k],cfg);}}
function buildSteps(preserve=null){steps=[];let x=35;for(let t=0;t<T();t++){offsets[t]=x;x+=expanded[t]?550:250;}
 if(mode==='forward'){for(let t=0;t<T();t++)if(expanded[t])for(let p=0;p<9;p++)steps.push({t,p});else steps.push({t,p:9});steps.push({t:T()-1,p:10});}
 if(mode==='backward'){steps.push({t:T()-1,p:10});for(let t=T()-1;t>=0;t--)if(expanded[t])for(let p=0;p<8;p++)steps.push({t,p});else steps.push({t,p:9});}
 if(mode==='update')for(const key of Object.keys(models[kind()].p))steps.push({t:T()-1,p:11,key});
 index=preserve?Math.max(0,steps.findIndex(s=>s.t===preserve.t&&(preserve.p===10?s.p===10:expanded[s.t]?s.p===(preserve.p===9?0:preserve.p):s.p===9))):0;
}
function reset(next=cfg,newWarning=warning){stopPlay();stopTraining();cfg=next;warning=newWarning;lastUpdates={};models={RNN:M.create('RNN',cfg),LSTM:M.create('LSTM',cfg)};expanded=Array.from({length:T()},(_,t)=>t<2);mode='forward';index=0;
 for(const k of ['RNN','LSTM']){const b=M.batch(models[k],cfg);models[k].history.push({epoch:0,loss:b.loss,warning:b.traces[1].prob,healthy:b.traces[0].prob,norm:b.norm});}
 $('unit').innerHTML=Array.from({length:cfg.units},(_,j)=>`<option value="${j}">${j+1}</option>`).join('');refresh();buildSteps();render(false,true);}
function rowCell(t){const x=offsets[t],u=unit(),s=steps[index],active=s.t===t,p=s.p,r=traces.RNN.cache[t],d=traces.LSTM.cache[t],g=el('g',{transform:`translate(${x},35)`});world.append(g);const width=expanded[t]?500:200;
 text(g,10,0,`t = ${t+1} · ${token(t)}`,'small','start');
 box(g,0,22,width,140,'','',active&&kind()==='RNN');text(g,15,49,'RNN','small','start');
 path(g,'M -25 105 H 225',`RNN-${t}-h`,C.hidden,active);
 if(expanded[t]){path(g,'M 20 105 H 125',`RNN-${t}-input`,C.input,active);path(g,'M 215 105 H 285',`RNN-${t}-linear`,C.ink,active);path(g,'M 375 105 H 525',`RNN-${t}-out`,C.hidden,active);box(g,125,74,90,58,'Wx+Uh+b',num(r.z.r[u]),active&&p===1);box(g,285,74,90,58,'tanh',num(r.h[u]),active&&p>=2);text(g,490,149,`h = ${num(r.h[u])}`,'small','end');}
 else{box(g,45,75,110,60,'RNN',num(r.h[u]),active&&kind()==='RNN');text(g,100,152,'one hidden state','small');}
 if(mode==='backward')text(g,width/2,187,`∥∂L/∂hₜ∥ = ${num(backs.RNN.steps[t].dhNorm)}`,'small');
 const a=el('g',{transform:'translate(0,220)'});g.append(a);box(a,0,0,width,414,'','',active&&kind()==='LSTM');text(a,15,29,'LSTM','small','start');
 if(!expanded[t]){path(a,'M -25 85 H 225',`LSTM-${t}-c`,C.memory,active);path(a,'M -25 370 H 225',`LSTM-${t}-h`,C.hidden,active);box(a,37,160,126,90,'LSTM cell',num(d.c[u]),active);text(a,100,65,`c = ${num(d.c[u])}`,'green value');text(a,100,403,`h = ${num(d.h[u])}`,'purple value');text(a,100,277,'f, i, g, o inside','small');}
 else{const xs=[82,194,306,418],gy=245;
 path(a,'M -25 86 H 65',`LSTM-${t}-cin`,C.memory,active);path(a,'M 99 86 H 290',`LSTM-${t}-keep`,C.memory,active);path(a,'M 323 86 H 525',`LSTM-${t}-c`,C.memory,active);
 path(a,'M -25 370 H 34 V 318 H 418',`LSTM-${t}-hin`,C.hidden,active);path(a,'M 82 398 V 301 H 418',`LSTM-${t}-input`,C.input,active);
 for(let j=0;j<4;j++)path(a,`M ${xs[j]} 318 V 276`,`LSTM-${t}-${['f','i','g','o'][j]}in`,C.hidden,active);
 path(a,'M 82 215 V 103',`LSTM-${t}-f`,C.ink,active);path(a,'M 194 215 V 153 H 289',`LSTM-${t}-i`,C.ink,active);path(a,'M 306 215 V 170',`LSTM-${t}-g`,C.ink,active);path(a,'M 306 135 V 103',`LSTM-${t}-write`,C.memory,active);
 path(a,'M 465 86 V 128',`LSTM-${t}-copy`,C.memory,active);path(a,'M 465 186 V 370 H 435',`LSTM-${t}-copyout`,C.hidden,active);path(a,'M 418 275 V 353',`LSTM-${t}-o`,C.ink,active);path(a,'M 436 370 H 525',`LSTM-${t}-h`,C.hidden,active);
 op(a,82,86,'×',active&&p===4);op(a,306,153,'×',active&&p===4);op(a,306,86,'+',active&&p===5);op(a,418,370,'×',active&&p===7);
 for(const[j,k,title,phase]of [[0,'f','σ · f',1],[1,'i','σ · i',2],[2,'g','tanh · g',3],[3,'o','σ · o',6]]){box(a,xs[j]-42,215,84,60,title,num(d[k][u]),active&&kind()==='LSTM'&&p===phase);}
 box(a,432,128,65,58,'tanh',num(Math.tanh(d.c[u])),active&&p===7);text(a,13,66,`cprev ${num(d.cp[u])}`,'green value','start');text(a,488,66,`c ${num(d.c[u])}`,'green value','end');text(a,488,403,`h ${num(d.h[u])}`,'purple value','end');}
 text(a,width/2,445,`x = ${token(t)} · unit ${u+1}`,'small');if(mode==='backward')text(a,width/2,475,`∥∂L/∂cₜ∥ = ${num(backs.LSTM.steps[t].dcNorm)}`,'small green');
}
function updateRecord(k){const b=batches[k];return lastUpdates[k]||{before:models[k].p,after:null,grad:b.grad,factor:cfg.clip>0&&b.norm>cfg.clip?cfg.clip/b.norm:1,norm:b.norm,preview:true};}
function selectedParameter(k,key){const record=updateRecord(k),value=record.before[key],indices=typeof value==='number'?[]:Array.isArray(value[0])?[unit(),0]:[unit()];const item={key,indices},before=M.valueAt(record.before,item),grad=M.valueAt(record.grad,item),delta=-cfg.rate*record.factor*grad,after=record.after?M.valueAt(record.after,item):before+delta;return {record,item,before,grad,delta,after,label:key+(indices.length?'['+indices.join(',')+']':'')};}
function drawUpdate(){const key=steps[index].key,k=kind(),a=selectedParameter(k,key);for(const[j,name]of ['RNN','LSTM'].entries()){const record=updateRecord(name),g=el('g',{transform:`translate(35,${j*260+40})`});world.append(g);text(g,20,0,name,'','start');for(const [x,title,value]of [[0,'Batch gradient',num(record.norm)],[270,'Clip factor',num(record.factor)],[540,'SGD update','η = '+cfg.rate]])box(g,x,35,220,100,title,value,name===k);path(g,'M 220 85 H 265',name+'-clip',C.warning,true);path(g,'M 490 85 H 535',name+'-sgd',C.memory,true);text(g,0,168,record.preview?'Preview: press Apply one epoch to commit':'Applied: epoch '+models[name].epoch,'small','start');}text(world,400,615,`${a.label}: ${num(a.before)} → ${num(a.after)}`,'value');}
function draw(){serial++;cancelAnimationFrame(frame);world.replaceChildren();if(mode==='update')drawUpdate();else for(let t=0;t<T();t++)rowCell(t);applyCamera();}
function applyCamera(){world.setAttribute('transform',`translate(${camera.x},${camera.y}) scale(${camera.k})`);}
function reframe(){const r=svg.getBoundingClientRect(),s=steps[index];if(mode==='update'){camera.k=Math.min(r.width/840,r.height/660);camera.x=(r.width-820*camera.k)/2;camera.y=(r.height-660*camera.k)/2;}else if(view==='overview'){const w=offsets[T()-1]+(expanded[T()-1]?550:250);camera.k=Math.min(r.width/w,r.height/760);camera.x=15;camera.y=(r.height-760*camera.k)/2;}else{const w=expanded[s.t]?570:310;camera.k=Math.min(r.width/w,r.height/760,1.4);camera.x=r.width/2-(offsets[s.t]+(expanded[s.t]?250:100))*camera.k;camera.y=(r.height-740*camera.k)/2;}applyCamera();}
function animate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const s=steps[index],k=kind();let routes=[];
 if(mode==='update')routes=[`${k}-clip`,`${k}-sgd`];else if(k==='RNN')routes=[`RNN-${s.t}-${expanded[s.t]?'out':'h'}`];else{const p=s.p,keys=!expanded[s.t]?['c','h']:p===0?['cin','input','hin']:p===1?['fin','f']:p===2?['iin','i']:p===3?['gin','g']:p===4?['keep','write']:p===5?['c']:p===6?['oin','o']:p===7?['copy','copyout','h']:['c','h'];routes=keys.map(v=>`LSTM-${s.t}-${v}`);}
 const dots=routes.map(id=>{const path=world.querySelector(`[data-route="${id}"]`);if(!path)return null;const dot=el('circle',{r:6,fill:mode==='backward'?C.warning:C.memory});path.parentElement.append(dot);return{path,dot,length:path.getTotalLength()};}).filter(Boolean);const start=performance.now(),id=++serial,duration=Math.min(1800,Number($('speed').value)*.65);function tick(now){if(id!==serial)return;const p=Math.min(1,(now-start)/duration);for(const d of dots){const q=d.path.getPointAtLength(d.length*(mode==='backward'?1-p:p));d.dot.setAttribute('cx',q.x);d.dot.setAttribute('cy',q.y);}if(p<1)frame=requestAnimationFrame(tick);else dots.forEach(d=>d.dot.remove());}frame=requestAnimationFrame(tick);}
function forwardDetail(k,s,d,u){const model=models[k],p=model.p,t=s.t+1;
 if(s.p===10)return ['Final inspection','Use the final hidden state to estimate whether the early precursor was present.','z = vᵀhT + bᵧ; p = σ(z)<br>L = −y log(p) − (1−y) log(1−p)',`z = ${num(traces[k].logit)}<br>p = ${num(traces[k].prob)}<br>y = ${warning?1:0}; loss = ${num(traces[k].loss)}`,traces[k].prob>=cfg.threshold?'Check needed':'No check needed','A recent normal reading does not cancel an earlier warning.','A readout converts remembered evidence into the task decision.'];
 if(k==='RNN')return [s.p===0?'RNN inputs':s.p===1?'RNN affine transform':s.p===2?'RNN tanh activation':'RNN hidden state','This RNN has one state path. Every reading recomputes that state.','zₜ = Wᵣxₜ + Uᵣhₜ₋₁ + bᵣ<br>hₜ = tanh(zₜ)',`xₜ = ${vec(d.x)}<br>hprev = ${vec(d.hp)}<br>zₜ[${u}] = ${num(d.z.r[u])}<br>hₜ[${u}] = ${num(d.h[u])}`,`h = ${num(d.h[u])}`,'Each recurrent multiplication can weaken the early signal.','The recurrent state combines the new observation with prior context; there is no separate cell-state lane.'];
 const a=key=>`${vec(p['W'+key][u])} · ${vec(d.x)}<br>+ ${vec(p['U'+key][u])} · ${vec(d.hp)}<br>+ ${num(p['b'+key][u])}`;
 const rows=[
 ['LSTM inputs','Gates use the same token and previous hidden state. Memory c travels separately.','zₐ = Wₐxₜ + Uₐhₜ₋₁ + bₐ',`xₜ = ${vec(d.x)}<br>hprev = ${vec(d.hp)}<br>cprev = ${vec(d.cp)}`,`cprev = ${num(d.cp[u])}`,'Bring the new observation and previous context together.','Numerical encoding lets shared weights process the sequence.'],
 ['Forget gate','Choose how much old memory to retain.','fₜ = σ(Wfxₜ + Ufhₜ₋₁ + bf)',`${a('f')}<br>zբ = ${num(d.z.f[u])}<br>fₜ = ${num(d.f[u])}`,`${(100*d.f[u]).toFixed(2)}% retained`,'The green memory lane is multiplied by a value near one.','Keep the early precursor through normal readings rather than overwrite it.'],
 ['Input gate','Choose how much new candidate content to admit.','iₜ = σ(Wᵢxₜ + Uᵢhₜ₋₁ + bᵢ)',`${a('i')}<br>zᵢ = ${num(d.z.i[u])}<br>iₜ = ${num(d.i[u])}`,`i = ${num(d.i[u])}`,'Normal readings can mostly close the write gate.','Selective writing protects useful memory from unrelated observations.'],
 ['Candidate content','Propose signed content for memory.','gₜ = tanh(Wgxₜ + Ughₜ₋₁ + bg)',`${a('g')}<br>zg = ${num(d.z.g[u])}<br>gₜ = ${num(d.g[u])}`,`g = ${num(d.g[u])}`,'A warning proposes content; an ordinary reading initially proposes zero.','Separate what might be stored from how much is accepted.'],
 ['Retain and write','Scale old memory and new content separately.','retained = fₜ ⊙ cₜ₋₁<br>new = iₜ ⊙ gₜ',`retained = ${num(d.f[u])} × ${num(d.cp[u])}<br>= ${num(d.f[u]*d.cp[u])}<br>new = ${num(d.i[u])} × ${num(d.g[u])}<br>= ${num(d.i[u]*d.g[u])}`,`kept ${num(d.f[u]*d.cp[u])}`,'The old precursor does not need to be written again at every reading.','Independent multiplication controls retention and writing.'],
 ['Cell-state update','Add accepted content to retained memory.','cₜ = fₜ ⊙ cₜ₋₁ + iₜ ⊙ gₜ',`${num(d.f[u]*d.cp[u])} + ${num(d.i[u]*d.g[u])}<br>cₜ = ${num(d.c[u])}`,`c = ${num(d.c[u])}`,'The additive green lane carries the warning across time.','Avoid completely recomputing useful memory from each input.'],
 ['Output gate','Choose how much memory becomes visible.','oₜ = σ(Wₒxₜ + Uₒhₜ₋₁ + bₒ)',`${a('o')}<br>zₒ = ${num(d.z.o[u])}<br>oₜ = ${num(d.o[u])}`,`o = ${num(d.o[u])}`,'The query initially opens this gate much more than normal readings.','Expose the memory when the inspection readout needs it.'],
 ['Hidden-state output','Squash a copy of memory, then scale it.','hₜ = oₜ ⊙ tanh(cₜ)',`${num(d.o[u])} × tanh(${num(d.c[u])})<br>hₜ = ${num(d.h[u])}`,`h = ${num(d.h[u])}`,'Small h does not imply small internal c.','Create an exposed signal for the next cell and final readout.'],
 ['Pass both states','Pass memory and exposed state to the next time step.',`(c${t}, h${t}) → ${s.t===T()-1?'readout':'next cell'}`,`cₜ = ${vec(d.c)}<br>hₜ = ${vec(d.h)}`,`memory ${num(d.c[u])}`,'The two lanes have different jobs.','Continue the sequence with the same parameters.'],
 ['Complete LSTM cell','This collapsed step runs all gates and both state updates.','f, i, o = σ(Wx + Uh + b)<br>g = tanh(Wgx + Ugh + bg)<br>cₜ = fₜcₜ₋₁ + iₜgₜ<br>hₜ = oₜ tanh(cₜ)',`f = ${num(d.f[u])}; i = ${num(d.i[u])}<br>g = ${num(d.g[u])}; o = ${num(d.o[u])}<br>c = ${num(d.c[u])}; h = ${num(d.h[u])}`,`memory ${num(d.c[u])}`,'All gate operations still happen; they are grouped for presentation.','Follow the long gap without stopping at every internal operation.']
 ];return rows[s.p];}
function backwardDetail(k,s,d,u){const b=backs[k],q=b.steps[s.t];if(s.p===10)return ['Start at the loss','Differentiate the loss through the sigmoid readout.','∂L/∂z = p − y<br>∂L/∂hT = (p−y)v',`p − y = ${num(b.dzOut)}<br>∂L/∂hT = ${vec(q.dh)}<br>sample loss = ${num(traces[k].loss)}`,`loss seed ${num(b.dzOut)}`,'The error signal starts at the inspection.','Find how the output should change before sending correction backward.'];
 if(k==='RNN')return ['RNN backward chain','Each step multiplies by both the tanh derivative and recurrent weights.','δₜ = (∂L/∂hₜ) ⊙ (1−hₜ²)<br>∂L/∂hₜ₋₁ = Uᵣᵀδₜ<br>∂L/∂Wᵣ += δₜxₜᵀ',`∂L/∂hₜ = ${vec(q.dh)}<br>1−h² = ${num(1-d.h[u]*d.h[u])}<br>δₜ = ${vec(q.dz.r)}<br>∂L/∂hprev = ${vec(q.dhp)}`,`gradient norm ${num(q.dhNorm)}`,'Repeated factors below one shrink corrections; unsaturated factors above one can amplify them.','Backpropagation measures which earlier parameters contributed to the final loss.'];
 const rows=[
 ['Incoming hidden gradient','Collect the loss correction entering this time step.','dhₜ = ∂L/∂hₜ',`dhₜ = ${vec(q.dh)}<br>∥dhₜ∥ = ${num(q.dhNorm)}`,`dh ${num(q.dh[u])}`,'A final mistake needs to reach the early precursor.','Start the local chain rule with the incoming correction.'],
 ['Cell-state gradient','Add the carried cell-state correction and the hidden-output contribution.','dcₜ = dc(next) + dhₜ ⊙ oₜ ⊙ (1−tanh²(cₜ))',`dhₜ = ${num(q.dh[u])}<br>oₜ = ${num(d.o[u])}<br>dcₜ = ${vec(q.dc)}`,`memory gradient ${num(q.dc[u])}`,'The green memory lane carries correction directly through the forget gates.','Combine both routes through which this memory affects the loss.'],
 ['Output-gate derivative','Differentiate the exposed hidden state and sigmoid gate.','δₒ = dhₜ ⊙ tanh(cₜ) ⊙ oₜ(1−oₜ)',`${num(q.dh[u])} × ${num(Math.tanh(d.c[u]))}<br>× ${num(d.o[u]*(1-d.o[u]))}<br>δₒ = ${num(q.dz.o[u])}`,`δo ${num(q.dz.o[u])}`,'Adjust the window onto the memory.','Learn how much content should be exposed.'],
 ['Forget-gate derivative','Differentiate retained old memory and the sigmoid.','δf = dcₜ ⊙ cₜ₋₁ ⊙ fₜ(1−fₜ)',`${num(q.dc[u])} × ${num(d.cp[u])}<br>× ${num(d.f[u]*(1-d.f[u]))}<br>δf = ${num(q.dz.f[u])}`,`δf ${num(q.dz.f[u])}`,'A wrong decision can teach the cell to retain more or less.','Learn the retention policy from the final loss.'],
 ['Input-gate derivative','Differentiate accepted candidate content and the sigmoid.','δᵢ = dcₜ ⊙ gₜ ⊙ iₜ(1−iₜ)',`${num(q.dc[u])} × ${num(d.g[u])}<br>× ${num(d.i[u]*(1-d.i[u]))}<br>δᵢ = ${num(q.dz.i[u])}`,`δi ${num(q.dz.i[u])}`,'Adjust how readily observations enter memory.','Learn which inputs deserve to be stored.'],
 ['Candidate derivative','Differentiate the candidate tanh.','δg = dcₜ ⊙ iₜ ⊙ (1−gₜ²)',`${num(q.dc[u])} × ${num(d.i[u])}<br>× ${num(1-d.g[u]*d.g[u])}<br>δg = ${num(q.dz.g[u])}`,`δg ${num(q.dz.g[u])}`,'Adjust the content proposed for storage.','Learn how an input should be represented in memory.'],
 ['Propagate to previous states','Send the direct memory gradient and all recurrent gate contributions backward.','dcₜ₋₁ = dcₜ ⊙ fₜ<br>dhₜ₋₁ = Σₐ Uₐᵀδₐ',`dcprev = ${vec(q.dcp)}<br>dhprev = ${vec(q.dhp)}<br>direct memory factor f = ${num(d.f[u])}`,`passed dc ${num(q.dcp[u])}`,'Near-one forget gates preserve the direct correction path.','Give earlier time steps credit for the final decision.'],
 ['Accumulate shared-parameter gradients','Add every time step’s contribution to each shared weight.','∂L/∂Wₐ += δₐxₜᵀ<br>∂L/∂Uₐ += δₐhₜ₋₁ᵀ<br>∂L/∂bₐ += δₐ',`this step, Wg[${u},0]:<br>${num(q.dz.g[u])} × ${num(d.x[0])}<br>whole sequence: ${num(b.grad.Wg[u][0])}`,`Σ gradient ${num(b.grad.Wg[u][0])}`,'One weight is used repeatedly, so all its uses contribute.','Update shared parameters using total sequence credit.']
 ];if(s.p===9)return ['Complete LSTM backward step','Compute all gate derivatives and pass both gradient states backward.','δf, δᵢ, δg, δₒ → ∇W, ∇U, ∇b<br>dcprev = dcₜ ⊙ fₜ<br>dhprev = Σₐ Uₐᵀδₐ',`δf = ${num(q.dz.f[u])}; δi = ${num(q.dz.i[u])}<br>δg = ${num(q.dz.g[u])}; δo = ${num(q.dz.o[u])}<br>dcprev = ${num(q.dcp[u])}<br>dhprev = ${num(q.dhp[u])}`,`memory gradient ${num(q.dc[u])}`,'Correction survives along a memory path controlled by f.','Differentiate all internal operations even when the cell is collapsed.'];return rows[s.p];}
function updateDetail(k,s){const a=selectedParameter(k,s.key),r=a.record;return [r.preview?'Preview an SGD update':'An applied weight update',r.preview?'This is the next averaged-batch update. Apply one epoch to commit all parameters.':'These are the recorded values before and after the last committed epoch.','g = (ghealthy + gwarning) / 2<br>α = min(1, clip / ∥g∥) [if enabled]<br>θnew = θold − η α gθ',`${a.label}<br>θold = ${num(a.before)}<br>gθ = ${num(a.grad)}; ∥g∥ = ${num(r.norm)}<br>α = ${num(r.factor)}; η = ${cfg.rate}<br>Δθ = ${num(a.delta)}<br>θnew = ${num(a.after)}`,`${num(a.before)} → ${num(a.after)}`,'Move each parameter in the direction that locally reduces average loss.','Training changes the model’s memory policy and readout through the calculated gradients.'];}
function math(s){return s.replaceAll('բ','f').replace(/([WUbzδ])([figo])/g,'$1<sub>$2</sub>');}
function details(){const k=kind(),s=steps[index],u=unit(),d=traces[k].cache[s.t],model=models[k];const info=mode==='forward'?forwardDetail(k,s,d,u):mode==='backward'?backwardDetail(k,s,d,u):updateDetail(k,s);
 $('detail-phase').textContent=`${k} · ${mode.toUpperCase()} · ${mode==='update'?'epoch '+model.epoch:'t = '+(s.t+1)+' / '+T()} · unit ${u+1}`;
 for(const[id,v]of [['detail-title',info[0]],['detail-explanation',info[1]],['detail-result',info[4]],['intuition',info[5]],['purpose',info[6]]])$(id).textContent=v;$('formula').innerHTML=math(info[2]);$('numbers').innerHTML=math(info[3]);
 const paramKeys=mode==='update'?[s.key]:k==='RNN'?['Wr','Ur','br','v','bv']:s.p===10?['v','bv']:mode==='forward'&&[1,2,3,6].includes(s.p)?['W'+({1:'f',2:'i',3:'g',6:'o'}[s.p]),'U'+({1:'f',2:'i',3:'g',6:'o'}[s.p]),'b'+({1:'f',2:'i',3:'g',6:'o'}[s.p])]:Object.keys(model.p);
 $('parameters').innerHTML=paramKeys.map(key=>{const v=model.p[key],display=typeof v==='number'?num(v):Array.isArray(v[0])?vec(v[u]):num(v[u]);return `<div class="param-row"><strong>${key}${Array.isArray(v)?' · unit '+(u+1):''}</strong>${display}</div>`;}).join('')+`<p>All weights and biases update. Gate activations, states, and gradients are calculated values, not parameters.</p>`;
 const rows=[['Hidden units',cfg.units],['Input features',3],['Sequence length',T()],['Recurrent layers',1],['Learning rate',cfg.rate],['Maximum epochs',cfg.epochs],['Loss target',cfg.tolerance],['Plateau patience',cfg.patience],['Minimum change',cfg.minDelta],['Clip norm',cfg.clip||'Off'],['Decision threshold',cfg.threshold]];$('hyperparameters').innerHTML='<div class="hyper-grid">'+rows.map(([a,b])=>`<span>${a}</span><strong>${b}</strong>`).join('')+'</div><p>SGD · full batch of 2 examples · binary cross-entropy. Sequence length and decision threshold are task settings. Edit the controls, then Apply settings.</p>';
 $('detail-note').textContent=mode==='backward'?'Backward numbers are actual sample-loss derivatives. Training averages derivatives from both examples. The direct cell-state path is one route; indirect gate paths are included in backpropagation.':'Initialization is illustrative. Predictions and training results come from the current parameters; changing settings can change the outcome.';
}
function chart(){const svg=$('loss-chart'),w=Math.max(280,svg.clientWidth),h=155;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.replaceChildren();const all=[...models.RNN.history,...models.LSTM.history].filter(p=>Number.isFinite(p.loss)),maxEpoch=Math.max(1,...all.map(p=>p.epoch)),maxLoss=Math.max(.1,...all.map(p=>p.loss)),X=e=>45+e/maxEpoch*(w-65),Y=v=>120-v/maxLoss*90;
 svg.append(el('path',{d:`M45 22 V120 H${w-20}`,fill:'none',stroke:'#b1bfc7'}));text(svg,5,15,'Loss','small','start');text(svg,w-22,147,'Epoch','small','end');
 for(const v of [0,maxLoss/2,maxLoss]){svg.append(el('line',{x1:45,y1:Y(v),x2:w-20,y2:Y(v),stroke:'#d6dfe3','stroke-width':.6}));text(svg,39,Y(v)+4,v.toFixed(2),'small','end');}text(svg,45,138,'0','small');text(svg,w-20,138,String(maxEpoch),'small');
 for(const[k,color]of [['RNN',C.warning],['LSTM',C.memory]]){const values=models[k].history.filter(p=>Number.isFinite(p.loss));const d=values.map((p,i)=>`${i?'L':'M'}${X(p.epoch)} ${Y(p.loss)}`).join(' ');svg.append(el('path',{d,stroke:color,'stroke-width':2,fill:'none'}));if(values.length===1)svg.append(el('circle',{cx:X(0),cy:Y(values[0].loss),r:3,fill:color}));text(svg,k==='RNN'?80:145,15,k,'small');svg.lastChild.setAttribute('style','fill:'+color);}
}
function updateUI(){const s=steps[index],u=unit();$('target').textContent=`Expected: ${warning?'Check needed':'No check needed'}`;
 $('outcomes').innerHTML=['RNN','LSTM'].map(k=>{const t=traces[k],decision=t.prob>=cfg.threshold,correct=decision===warning;return `<div class="outcome ${correct?'correct':'wrong'}"><span>${k} · epoch ${models[k].epoch}</span><strong>${decision?'Check needed':'No check needed'}</strong><span class="small">${(t.prob*100).toFixed(1)}% warning probability · ${correct?'correct':'misses target'}</span><span class="small">Full-sequence readout · threshold ${(cfg.threshold*100).toFixed(0)}%</span></div>`;}).join('');
 $('step-label').textContent=mode==='update'?`${kind()} · ${s.key}`:`t = ${s.t+1} · ${token(s.t)} · ${s.p===10?'readout / loss':mode==='forward'?s.p===9?'whole cell':fwd[s.p]:s.p===9?'whole backward cell':bwd[s.p]}`;
 $('expand').disabled=mode==='update';$('expand').textContent=expanded[s.t]?'Collapse current cell':'Expand current cell';$('expand').setAttribute('aria-expanded',String(expanded[s.t]));
 $('timeline').innerHTML=Array.from({length:T()},(_,t)=>`<button data-t="${t}" class="${t===s.t?'active ':''}${expanded[t]?'expanded ':''}${t===0&&warning?'warning':''}" aria-label="Time ${t+1}, ${token(t)}, ${expanded[t]?'expanded':'collapsed'}">${t===0?'⚑':t===T()-1?'?':t+1}</button>`).join('');$('timeline').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(mode==='update')setMode('forward');const t=Number(b.dataset.t),i=steps.findIndex(s=>s.t===t&&s.p!==10);jump(i<0?0:i);});
 $('step-count').textContent=`${index+1} / ${steps.length}`;$('previous').disabled=index===0;$('next').disabled=index===steps.length-1;$('play').textContent=playing?'Pause':'Play';$('train').textContent=training?'Stop training':'Run configured epochs';$('one-epoch').disabled=training||['RNN','LSTM'].every(k=>models[k].epoch>=cfg.epochs||models[k].status==='Numerical divergence');
 document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));
 const d=traces.LSTM.cache[s.t];let product=1;for(let t=1;t<=s.t;t++)product*=traces.LSTM.cache[t].f[u];$('memory-note').textContent=mode==='update'?`Actual full-batch gradients update every parameter. Clipping scales the vector, preserving its direction. ${lastUpdates[kind()]?'The inspector shows the last applied epoch.':'The inspector shows the next update as a preview.'}`:`Highlighted green path: cₜ = fₜcₜ₋₁ + iₜgₜ. At this cell, f = ${num(d.f[u])}; the direct retention product since the first cell is ${num(product)}. ${warning?'The precursor lives in c, even when h is small.':'Healthy control: there is no early precursor to store.'}`;
 $('training-status').innerHTML=['RNN','LSTM'].map(k=>`${k}: epoch ${models[k].epoch}/${cfg.epochs} · mean loss ${num(batches[k].loss)} · ${models[k].status} · batch gradient norm ${num(batches[k].norm)}`).join('<br>');details();chart();$('announce').textContent=$('step-label').textContent;
}
function render(motion=false,focus=false){draw();updateUI();if(focus)reframe();if(motion)animate();}
function stopPlay(){playing=false;clearTimeout(timer);}
function stopTraining(){training=false;clearTimeout(trainTimer);}
function jump(i){stopPlay();const old=steps[index]?.t;index=Math.max(0,Math.min(steps.length-1,i));render(true,old!==steps[index].t);}
function setMode(next){stopPlay();mode=next;buildSteps();render(true,true);}
function schedule(){clearTimeout(timer);if(!playing)return;timer=setTimeout(()=>{if(index>=steps.length-1){stopPlay();updateUI();return;}const old=steps[index].t;index++;render(true,old!==steps[index].t);schedule();},Number($('speed').value));}
function epoch(){stopPlay();for(const k of ['RNN','LSTM'])if(models[k].epoch<cfg.epochs&&models[k].status!=='Numerical divergence'){lastUpdates[k]=M.epoch(models[k],cfg).update;if(models[k].epoch>=cfg.epochs&&models[k].status==='Training')models[k].status='Epoch limit; target not met';}refresh();render(false);}
function canTrain(k){return models[k].epoch<cfg.epochs&&!['Loss target met','Plateau above target','Numerical divergence'].includes(models[k].status);}
function runTraining(){if(training){stopTraining();updateUI();return;}stopPlay();training=true;function tick(){if(!training)return;let ran=false;for(const k of ['RNN','LSTM'])if(canTrain(k)){lastUpdates[k]=M.epoch(models[k],cfg).update;ran=true;}
 if(!ran){stopTraining();for(const k of ['RNN','LSTM'])if(models[k].epoch>=cfg.epochs&&models[k].status==='Training')models[k].status='Epoch limit; target not met';refresh();render();return;}refresh();render();trainTimer=setTimeout(tick,12);}tick();}
function readConfig(){const form=$('config-form');if(!form.reportValidity())return null;const data=new FormData(form),next={};for(const key of Object.keys(M.config()))next[key]=Number(data.get(key));return {cfg:M.config(next),warning:data.get('scenario')==='warning'};}
function preset(explode){const next=M.config(explode?{gap:40,recurrent:1.35,clip:0}:{});for(const[k,v]of Object.entries(next))$('config-form').elements[k].value=v;$('config-form').elements.scenario.value=explode?'healthy':'warning';reset(next,!explode);if(explode){$('inspect-model').value='RNN';setMode('backward');}else $('inspect-model').value='LSTM';render(false,true);}
function zoom(factor,x=svg.clientWidth/2,y=svg.clientHeight/2){const k=Math.max(.035,Math.min(3,camera.k*factor)),r=k/camera.k;camera.x=x-(x-camera.x)*r;camera.y=y-(y-camera.y)*r;camera.k=k;view='manual';applyCamera();}
svg.addEventListener('wheel',e=>{e.preventDefault();const r=svg.getBoundingClientRect();zoom(e.deltaY<0?1.14:1/1.14,e.clientX-r.left,e.clientY-r.top);},{passive:false});svg.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,cx:camera.x,cy:camera.y};svg.setPointerCapture(e.pointerId);svg.classList.add('dragging');});svg.addEventListener('pointermove',e=>{if(!drag)return;view='manual';camera.x=drag.cx+e.clientX-drag.x;camera.y=drag.cy+e.clientY-drag.y;applyCamera();});for(const event of ['pointerup','pointercancel'])svg.addEventListener(event,()=>{drag=null;svg.classList.remove('dragging');});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$('previous').onclick=()=>jump(index-1);$('next').onclick=()=>jump(index+1);$('restart').onclick=()=>jump(0);
$('play').onclick=()=>{if(playing){stopPlay();render();}else{if(index===steps.length-1)index=0;playing=true;render(true,true);schedule();}};$('speed').onchange=()=>{if(playing)schedule();};
$('expand').onclick=()=>{const s=steps[index];stopPlay();expanded[s.t]=!expanded[s.t];buildSteps(s);render(true,true);};$('inspect-model').onchange=()=>{if(mode==='update')buildSteps();render(false,true);};$('unit').onchange=()=>render(false);
$('one-epoch').onclick=()=>{epoch();mode='update';buildSteps();render(true,true);};$('train').onclick=runTraining;$('config-form').onsubmit=e=>{e.preventDefault();const c=readConfig();if(c)reset(c.cfg,c.warning);};$('memory-preset').onclick=()=>preset(false);$('explode-preset').onclick=()=>preset(true);
$('zoom-in').onclick=()=>zoom(1.25);$('zoom-out').onclick=()=>zoom(.8);$('fit').onclick=()=>{view='overview';reframe();};$('focus').onclick=()=>{view='focus';reframe();};
$('sidebar-toggle').onclick=()=>{const hidden=getComputedStyle($('settings')).display==='none';document.body.classList.toggle('controls-hidden',!hidden);document.body.classList.toggle('controls-open',hidden);$('sidebar-toggle').textContent=hidden?'Hide controls':'Show controls';$('sidebar-toggle').setAttribute('aria-expanded',String(hidden));requestAnimationFrame(reframe);};
async function fullscreen(){if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}$('fullscreen').onclick=()=>fullscreen().catch(()=>{});
$('model-details').onclick=()=>{stopPlay();$('weight-table').innerHTML=['RNN','LSTM'].map(k=>`<h3>${k} · epoch ${models[k].epoch}</h3><table><thead><tr><th>Parameter</th><th>Current value</th></tr></thead><tbody>${Object.entries(models[k].p).map(([key,value])=>`<tr><td>${key}</td><td>${typeof value==='number'?num(value):Array.isArray(value[0])?value.map(vec).join('<br>'):vec(value)}</td></tr>`).join('')}</tbody></table>`).join('');$('details').showModal();};$('close-details').onclick=()=>$('details').close();
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('details').open)return;if(e.key==='ArrowRight'){e.preventDefault();jump(index+1);}if(e.key==='ArrowLeft'){e.preventDefault();jump(index-1);}if(e.code==='Space'&&document.activeElement.tagName!=='BUTTON'){e.preventDefault();$('play').click();}if(e.key.toLowerCase()==='f')fullscreen().catch(()=>{});});
new ResizeObserver(()=>{if(view!=='manual')reframe();chart();}).observe(svg);
if(innerWidth<=900){document.body.classList.add('controls-hidden');$('sidebar-toggle').textContent='Show controls';$('sidebar-toggle').setAttribute('aria-expanded','false');}
reset();
})();
